// The structure bench (stage 5): the corpus truth and how a case is built.
//
// The truth is generated by `web/spikes/structure/corpus/build.py` (our own
// charts, fixed seeds) into `fixtures/corpus.json`. A « case » is one piece
// read at one error level, with or without the audio evidence and the known
// chart: it gives the `HarmonyInput` the detectors read, exactly in the shape
// the app will hand them, plus what the scorer needs to map answers back to
// the truth (bar lines of the input in source seconds).

import { readFileSync } from 'node:fs';
import { parseChord } from '../../harmony/parse';
import type { ChordSymbol, Key } from '../../model/harmony';
import type { PartType, StructureModeChoice } from '../../model/structure';
import type { StandardChart, ReadBar } from '../../standards/irealRead';
import type { HarmonyBar, HarmonyChord, HarmonyInput, KnownStandard } from '../types';
import { noisyChords, noisyGrid, NOISE, type NoiseLevel, type TimedChord } from './noise';
import { rng, seedOf } from './rng';
import { simulatedEvidence, type EvidenceKind } from './simEvidence';

// ---------------------------------------------------------------- truth

export interface TruthChord {
  /** Beat in the bar, 0-based. */
  beat: number;
  text: string;
}

export interface TruthBar {
  start: number;
  end: number;
  beats: number;
  /** 1-based chorus of the form; null outside the form (intro, outro, tag) and in pop pieces. */
  chorus: number | null;
  /** Section letter; null outside the form. */
  section: string | null;
  /** Bar index inside its section (or its intro / outro). */
  pos: number;
  /** Index in `TruthPiece.parts`. */
  part: number;
  /** As played (reharmonisations and extensions included). */
  chords: TruthChord[];
  /** Who leads this bar: part instrument id, stem, role (`head`, `solo`, `intro`); null: the band alone. */
  lead: { instrument: string; stem: string; role: string } | null;
  /** Nominal level of each stem (linear RMS), what Tier S simulates the separation from. */
  play: Record<string, number>;
}

export interface TruthKey extends Key {
  name: string;
}

export interface TruthPart {
  type: PartType;
  number: number;
  /** Part instrument id (`model/structure.ts#PART_INSTRUMENTS`); null for intro, outro. */
  instrument: string | null;
  /** The arranger's instrument (tenor, alto, mutedtrumpet…). */
  lead: string | null;
  firstBar: number;
  endBar: number;
  letters: string;
}

export type WrittenLabel = { letter: string } | { part: PartType };

export interface TruthWrittenSection {
  id: string;
  label: WrittenLabel;
  bars: { beats: number; chords: TruthChord[]; simile: boolean }[];
  times: number;
  keyChange: TruthKey | null;
}

export interface TruthSimplified {
  form: { part: number; letters: string }[];
  sections: TruthWrittenSection[];
  /** [played bar, index in `sections`, bar offset in that section]. */
  places: [number, number, number][];
}

export interface TruthPiece {
  id: string;
  title: string;
  standard: boolean;
  style: string;
  mode: 'jazz' | 'pop';
  meter: number;
  bpm: number;
  key: TruthKey;
  /** In the default (fast) subset. */
  subset: boolean;
  duration: number;
  /** Letters of one chorus; '' for pop pieces. */
  form: string;
  /** The piece has a chorus form played at least twice: chorus length and form string are scored. */
  formScored: boolean;
  chorusBars: number | null;
  choruses: { chorus: number; firstBar: number; endBar: number }[];
  /** Section letters, one per bar where a section starts. */
  sections: { bar: number; label: string }[];
  parts: TruthPart[];
  /** Modulations: from `bar` on, the music is in `key` (the main key is `key`). */
  keyChanges: { bar: number; key: TruthKey }[];
  /** Null for a through-composed piece (nothing to fold). */
  simplified: TruthSimplified | null;
  /** The chart of one chorus as a collection would give it; null for pop pieces. */
  known: { title: string; key: TruthKey; meter: number; bars: { section: string | null; chords: TruthChord[] }[] } | null;
  /** Stem -> arranger instruments heard in it. */
  stems: Record<string, string[]>;
  bars: TruthBar[];
}

let cache: TruthPiece[] | null = null;

/** The whole corpus (35 pieces), from the committed fixture. */
export function loadCorpus(path?: string): TruthPiece[] {
  if (path) return JSON.parse(readFileSync(path, 'utf8')) as TruthPiece[];
  cache ??= JSON.parse(readFileSync(new URL('./fixtures/corpus.json', import.meta.url), 'utf8')) as TruthPiece[];
  return cache;
}

export function chordOf(text: string): ChordSymbol | null {
  const p = parseChord(text);
  if (!p.ok) throw new Error(`bench: cannot read chord ${text}`);
  return p.chord;
}

/** Source time of beat `beat` of a truth bar (beats evenly spread in the bar). */
export function beatTime(bar: { start: number; end: number; beats: number }, beat: number): number {
  return bar.start + ((bar.end - bar.start) * beat) / bar.beats;
}

/** Every chord change of the truth, as the analysis would give them (a chord lasts until the next). */
export function truthTimeline(piece: TruthPiece): TimedChord[] {
  const out: TimedChord[] = [];
  let prev: string | null = null;
  for (const b of piece.bars) {
    for (const c of b.chords) {
      if (c.text === prev) continue;
      out.push({ time: beatTime(b, c.beat), chord: chordOf(c.text), doubtful: false });
      prev = c.text;
    }
  }
  return out;
}

/** Bar lines of the truth (n + 1 times). */
export function truthLines(piece: TruthPiece): number[] {
  return [...piece.bars.map((b) => b.start), piece.bars[piece.bars.length - 1]!.end];
}

/** The truth bar containing `time` (clamped). */
export function truthBarAt(piece: TruthPiece, time: number): number {
  const bars = piece.bars;
  let lo = 0;
  let hi = bars.length - 1;
  if (time <= bars[0]!.start) return 0;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (bars[mid]!.start <= time + 1e-6) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/** The truth bar LINE nearest to `time` (0…n). */
export function nearestTruthLine(piece: TruthPiece, time: number): number {
  const lines = truthLines(piece);
  let best = 0;
  for (let i = 1; i < lines.length; i++) if (Math.abs(lines[i]! - time) < Math.abs(lines[best]! - time)) best = i;
  return best;
}

/** Bars of the chart in force, built from bar lines and a chord timeline as the app does. */
export function harmonyBars(lines: readonly number[], meter: number, chords: readonly TimedChord[]): HarmonyBar[] {
  const bars: HarmonyBar[] = [];
  let ci = 0;
  let sounding: TimedChord | null = null;
  for (let i = 0; i + 1 < lines.length; i++) {
    const start = lines[i]!;
    const end = lines[i + 1]!;
    const beatLen = (end - start) / meter;
    while (ci < chords.length && chords[ci]!.time < start - beatLen / 2) sounding = chords[ci++]!;
    const carried = sounding?.chord ?? null;
    const inBar: HarmonyChord[] = [];
    while (ci < chords.length && chords[ci]!.time < end - beatLen / 2) {
      const c = chords[ci++]!;
      sounding = c;
      const beat = Math.max(0, Math.min(meter - 1, Math.round((c.time - start) / beatLen)));
      const entry: HarmonyChord = { beat, chord: c.chord, doubtful: c.doubtful, byHand: false };
      const last = inBar[inBar.length - 1];
      if (last && last.beat === beat) inBar[inBar.length - 1] = entry;
      else inBar.push(entry);
    }
    bars.push({
      bar: i,
      start,
      end,
      beats: meter,
      meter: { numerator: meter, denominator: meter === 3 || meter === 4 ? 4 : 8 },
      chords: inBar,
      carried: inBar[0]?.beat === 0 ? null : carried,
    });
  }
  return bars;
}

/** The known chart of a piece, as `standards/irealRead` would give it. */
export function knownStandard(piece: TruthPiece): KnownStandard | null {
  const k = piece.known;
  if (!k) return null;
  const meter = { numerator: k.meter, denominator: 4 };
  const bars: ReadBar[] = k.bars.map((b, i) => {
    const chords = b.chords.map((c, j) => ({
      beat: c.beat,
      duration: (b.chords[j + 1]?.beat ?? k.meter) - c.beat,
      chord: chordOf(c.text),
      text: c.text,
      approximate: false,
    }));
    return { source: i, meter, chords, alternates: [], section: b.section, comments: [], pass: 1, ending: null, simile: null };
  });
  const chart: StandardChart = {
    index: 0,
    title: k.title,
    rawTitle: k.title,
    composer: '',
    composerRaw: '',
    style: piece.style === 'bossa' ? 'Bossa Nova' : piece.style === 'ballad' ? 'Ballad' : piece.style === 'waltz' ? 'Jazz Waltz' : 'Medium Swing',
    feel: null,
    key: { tonic: k.key.tonic, mode: k.key.mode },
    keyText: k.key.name,
    bpm: piece.bpm,
    meter,
    meters: [meter],
    writtenBars: bars.length,
    bars,
    warnings: [],
  };
  return { chart, titleScore: 0.95 };
}

// ---------------------------------------------------------------- cases

export interface CaseOptions {
  level: NoiseLevel;
  /** `stems`: ideal separation (+ timbre, + simulated wind recogniser); `mix`: no separation (timbre only); `none`: no audio evidence. */
  evidence: EvidenceKind;
  /** The known chart of the standard is found by the title (jazz pieces only). */
  known: boolean;
  mode?: StructureModeChoice;
  /** Extra seed (several draws of the same level). */
  draw?: number;
}

export interface BenchCase {
  piece: TruthPiece;
  options: CaseOptions;
  input: HarmonyInput;
  /** Label for tables: « realiste / pistes / grille ». */
  label: string;
}

export function caseLabel(o: CaseOptions): string {
  const ev = { stems: 'pistes', mix: 'sans séparation', none: 'sans audio' }[o.evidence];
  return `${o.level} / ${ev} / ${o.known ? 'grille connue' : 'sans grille'}`;
}

/** One case: the truth read through the simulated analysis errors of `options.level`. */
export function buildCase(piece: TruthPiece, options: CaseOptions): BenchCase {
  const r = rng(seedOf(`${piece.id}|${options.level}|${options.draw ?? 0}`));
  const noise = NOISE[options.level];
  const lines = noisyGrid(truthLines(piece), piece.meter, noise, r);
  const chords = noisyChords(truthTimeline(piece), piece, noise, r);
  const bars = harmonyBars(lines, piece.meter, chords);
  const known = options.known ? knownStandard(piece) : null;
  const evRng = rng(seedOf(`${piece.id}|${options.level}|ev|${options.draw ?? 0}`));
  const input: HarmonyInput = {
    bars,
    duration: piece.duration,
    key: { tonic: piece.key.tonic, mode: piece.key.mode },
    keyConfidence: options.level === 'parfait' ? 1 : 0.8,
    known: known ? [known] : [],
    evidence: simulatedEvidence(piece, bars, options.evidence, noise, evRng),
    mode: options.mode ?? 'auto',
  };
  return { piece, options, input, label: caseLabel(options) };
}
